<script setup lang="ts">
import { api,friendlyError } from '@lostsky/api/client';import LsButton from '@lostsky/ui/components/LsButton.vue';import LsField from '@lostsky/ui/components/LsField.vue';import LsFormList from '@lostsky/ui/components/LsFormList.vue';import LsInlineError from '@lostsky/ui/components/LsInlineError.vue';import LsPageHeader from '@lostsky/ui/components/LsPageHeader.vue';import LsFormActions from '@lostsky/ui/components/LsFormActions.vue';import LsFormSection from '@lostsky/ui/components/LsFormSection.vue';import LsSwitchField from '@lostsky/ui/components/LsSwitchField.vue';import { feedback } from '@lostsky/ui/feedback';import { useMutation,useQuery } from '@tanstack/vue-query';import { NInput,NInputNumber,NSelect } from 'naive-ui';import { computed,reactive,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { can } from '../session'
type Catalog={key:string;label:string;levels:number[]};type Ability={key:string;ability_key:string|null;level:number;duration_days:number};let seq=0;const make=():Ability=>({key:`new-${++seq}`,ability_key:null,level:1,duration_days:30});const route=useRoute();const router=useRouter();const id=computed(()=>Number(route.params.id||0));const editing=computed(()=>id.value>0);const form=reactive({name:'',is_active:1,abilities:[make()] as Ability[]});const catalog=useQuery({queryKey:['admin-ability-catalog'],queryFn:()=>api.get<Catalog[]>('/entitlements/ability-catalog')});const detail=useQuery({queryKey:computed(()=>['admin-entitlement-package',id.value]),queryFn:()=>api.get<any>(`/entitlements/packages/${id.value}`),enabled:editing});watch(()=>detail.data.value,d=>{if(d)Object.assign(form,{name:d.name,is_active:d.is_active,abilities:(d.abilities??[]).map((a:any)=>({key:`ability-${a.id}`,ability_key:a.ability_key,level:a.level,duration_days:a.duration_days}))})},{immediate:true});const abilityOptions=computed(()=>(catalog.data.value??[]).map(a=>({label:a.label,value:a.key})));const levels=(key:string|null)=>(catalog.data.value?.find(a=>a.key===key)?.levels??[1]).map(v=>({label:`等级 ${v}`,value:v}));const save=useMutation({mutationFn:()=>api.post<{id:number}>(editing.value?`/entitlements/packages/${id.value}`:'/entitlements/packages',{name:form.name,is_active:form.is_active,abilities:form.abilities.map(({ability_key,level,duration_days})=>({ability_key,level,duration_days}))}),onSuccess:data=>{feedback.success('Ability 权益包已保存');router.push(`/entitlements/packages/${data.id}`)}});const valid=computed(()=>Boolean(form.name.trim()&&form.abilities.length&&form.abilities.every(a=>a.ability_key&&a.duration_days>=0)))
</script><template><div class="entitlement-form"><LsPageHeader :title="editing?'编辑 Ability 权益包':'创建 Ability 权益包'" description="Ability 只能从代码目录选择；免费一个月默认填写 30 天。" back-to="/entitlements/packages" back-label="返回权益包"/><form @submit.prevent="save.mutate()"><LsFormSection title="基本信息"><LsField label="权益包名称" for-id="entitlement-name" required><NInput id="entitlement-name" v-model:value="form.name" maxlength="100"/></LsField><LsSwitchField id="entitlement-active" :model-value="form.is_active===1" label="启用状态" description="停用后不能用于新的权益活动。" @update:model-value="v=>form.is_active=v?1:0"/></LsFormSection><LsFormSection title="Ability"><LsFormList v-model="form.abilities" :item-key="a=>a.key" :create-item="make" item-label="Ability" add-label="添加 Ability"><template #item="{item}"><div class="ability-fields"><LsField label="Ability" :for-id="`ability-key-${item.key}`" required><NSelect :id="`ability-key-${item.key}`" v-model:value="item.ability_key" :options="abilityOptions"/></LsField><LsField label="等级" :for-id="`ability-level-${item.key}`"><NSelect :id="`ability-level-${item.key}`" v-model:value="item.level" :options="levels(item.ability_key)"/></LsField><LsField label="持续天数" :for-id="`ability-days-${item.key}`" hint="0 表示永久"><NInputNumber :id="`ability-days-${item.key}`" v-model:value="item.duration_days" :min="0"/></LsField></div></template></LsFormList></LsFormSection><LsInlineError v-if="detail.isError.value" :message="friendlyError(detail.error.value)"/><LsInlineError v-if="save.isError.value" :message="friendlyError(save.error.value)"/><LsFormActions><LsButton type="button" variant="secondary" @click="router.back()">取消</LsButton><LsButton type="submit" :disabled="!valid||!can('admin.entitlement.write')" :loading="save.isPending.value">保存权益包</LsButton></LsFormActions></form></div></template><style scoped>.entitlement-form,.entitlement-form form{display:grid;gap:1.25rem}.ability-fields{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.ability-fields>*:last-child{grid-column:1/-1}@media(max-width:639px){.ability-fields{grid-template-columns:1fr}.ability-fields>*:last-child{grid-column:auto}}</style>
